from typing import Callable, TypeVar, List

T = TypeVar('T')

def pipe(*functions: Callable) -> Callable:
    def piped(value):
        for func in functions:
            value = func(value)
        return value
    return piped

def uppercase(data: List[dict]) -> List[dict]:
    return [{**row, 'name': row['name'].upper()} for row in data]

def filter_by_amount(threshold: float):
    def filter_func(data: List[dict]) -> List[dict]:
